{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "todo-item",
  "title": "Todo Item",
  "description": "A single todo item stored in localStorage",
  "type": "object",
  "required": ["id", "title", "completed"],
  "properties": {
    "id": {
      "description": "Unique identifier for the todo item",
      "type": "string"
    },
    "title": {
      "description": "The todo item text",
      "type": "string"
    },
    "completed": {
      "description": "Whether the todo item is completed",
      "type": "boolean"
    }
  },
  "additionalProperties": false
}

{
  "watches": [
    {
      "name": "Visual state when empty",
      "scenarios": [
        "features/todos.feature:Main and footer are hidden when there are no todos"
      ]
    },
    {
      "name": "Creating todos",
      "scenarios": [
        "features/todos.feature:Create a new todo",
        "features/todos.feature:Whitespace in new todo is trimmed",
        "features/todos.feature:Empty todo is ignored"
      ]
    },
    {
      "name": "Toggling completion",
      "scenarios": [
        "features/todos.feature:Mark a todo as completed",
        "features/todos.feature:Mark all todos as completed",
        "features/todos.feature:Mark-all checkbox reflects individual completions"
      ]
    },
    {
      "name": "Editing todos",
      "scenarios": [
        "features/todos.feature:Double-click a todo to enter editing mode",
        "features/todos.feature:Save an edited todo on Enter",
        "features/todos.feature:Save an edited todo on blur",
        "features/todos.feature:Discard edit on Escape",
        "features/todos.feature:Destroy todo when edit is emptied"
      ]
    },
    {
      "name": "Counter",
      "scenarios": [
        "features/todos.feature:Display active todo count",
        "features/todos.feature:Pluralize item count"
      ]
    },
    {
      "name": "Clear completed",
      "scenarios": [
        "features/todos.feature:Clear completed removes completed todos",
        "features/todos.feature:Clear completed button is hidden when no completed todos exist"
      ]
    },
    {
      "name": "Routing and filtering",
      "scenarios": [
        "features/todos.feature:Show all todos by default",
        "features/todos.feature:Filter to active todos",
        "features/todos.feature:Filter to completed todos",
        "features/todos.feature:Active filter link has selected class"
      ]
    },
    {
      "name": "Persistence to localStorage",
      "scenarios": [
        "features/todos.feature:Persist todos across reload",
        "features/todos.feature:Persist completion state across reload",
        "features/todos.feature:Persist active filter across reload"
      ]
    },
    {
      "name": "Item shape contract",
      "scenarios": [
        "features/todos.feature:The todo item conforms to the todo-item schema"
      ]
    }
  ]
}

